// The Error Trigger payload has two shapes: `execution{}` when a node failed mid-run, and `trigger{}`
// when the failure was in the trigger itself (the workflow never executed, so there is no execution id).
// Both are flattened into one record shape so the GTMOS side has a single thing to read.
//
// `signals: []` is load-bearing. /api/v1/webhooks/n8n stores the raw body verbatim and then hands
// `payload.signals` to the signal processor; an empty list means the delivery is recorded as a
// processed webhook event carrying this record, without inventing any GTM data.
const out = [];
for (const item of $input.all()) {
  const p = item.json ?? {};
  const wf = p.workflow ?? {};
  const ex = p.execution ?? {};
  const tr = p.trigger ?? {};
  const err = ex.error ?? tr.error ?? {};
  const executionId = ex.id ?? null;
  const lastNode = ex.lastNodeExecuted ?? (err.node && err.node.name) ?? null;
  out.push({ json: {
    signals: [],
    // GTMOS dedupes on `event_id`, so a redelivery of the same failure collapses instead of piling up.
    event_id: 'n8n-error:' + (wf.id ?? 'unknown') + ':' + (executionId ?? 'trigger') + ':' + (lastNode ?? 'n-a'),
    record_type: 'n8n_workflow_error',
    recorded_by: 'n8n:06-error-handler',
    recorded_at: new Date().toISOString(),
    workflow_id: wf.id ?? null,
    workflow_name: wf.name ?? null,
    execution_id: executionId,
    execution_url: ex.url ?? null,
    execution_mode: ex.mode ?? tr.mode ?? null,
    retry_of: ex.retryOf ?? null,
    last_node_executed: lastNode,
    error_name: err.name ?? null,
    error_message: String(err.message ?? '').slice(0, 1000),
    error_stack: String(err.stack ?? '').slice(0, 2000)
  }});
  // Second, independent channel: make the n8n execution itself findable by the workflow that broke.
  // customData is Code-node only and is not available in every execution mode, hence the try/catch.
  try {
    $execution.customData.set('gtmos_failed_workflow', String(wf.name ?? wf.id ?? 'unknown').slice(0, 250));
    $execution.customData.set('gtmos_failed_execution', String(executionId ?? 'n/a'));
    $execution.customData.set('gtmos_failed_node', String(lastNode ?? 'n/a').slice(0, 250));
  } catch (e) { /* recording the error must never fail because of telemetry */ }
}
return out;

// X-GTMOS-Signature = sha256=HMAC(secret, `${timestamp}.${rawBody}`); GTMOS rejects >5 min skew.
const crypto = require('crypto');
const secret = $env.GTMOS_WEBHOOK_SECRET;
return $input.all().map((item) => {
  const body = JSON.stringify(item.json);
  const ts = Math.floor(Date.now() / 1000).toString();
  const sig = 'sha256=' + crypto.createHmac('sha256', secret).update(ts + '.' + body).digest('hex');
  return { json: { body, ts, sig } };
});

// Last line of defence. If GTMOS was the thing that was down, the POST above returned nothing useful;
// the record still has to survive somewhere an operator can read, so it goes to the execution log.
const results = [];
const records = $('Build operational record').all();
for (let i = 0; i < records.length; i++) {
  const posted = $input.all()[i] ? $input.all()[i].json : {};
  const status = posted.statusCode ?? null;
  const stored = posted.body && posted.body.id ? posted.body.id : null;
  const line = { gtmos_ops_record: records[i].json, delivery: { http_status: status, gtmos_event_id: stored, delivered: status === 200 || status === 202 } };
  console.log('GTMOS_N8N_ERROR ' + JSON.stringify(line));
  results.push({ json: line });
}
return results;
